const ZIP='{{store_zip}}', LAT=41.7508, LNG=-88.1535;
const ents=performance.getEntriesByType('resource').map(e=>e.name).filter(u=>/graphql/.test(u));
const find=op=>ents.find(u=>u.includes('operationName='+op));
const swap=(u,fn)=>{const x=new URL(u); const v=JSON.parse(x.searchParams.get('variables')); fn(v); x.searchParams.set('variables',JSON.stringify(v)); return x.toString();};
const out={};
const ds=find('DefaultShop'); if(!ds) return 'no DefaultShop url; ops='+ents.map(u=>new URL(u).searchParams.get('operationName')).slice(0,60).join(',');
const r1=await fetch(swap(ds,v=>{v.postalCode=ZIP; v.coordinates={latitude:LAT,longitude:LNG}; v.addressId=null;}),{credentials:'include'}); out.defaultShop=(await r1.text()).slice(0,1200);
const sc=find('ShopCollectionScoped'); if(sc){const r2=await fetch(swap(sc,v=>{v.postalCode=ZIP; v.coordinates={latitude:LAT,longitude:LNG};}),{credentials:'include'}); out.shopCollection=(await r2.text()).slice(0,1500);}
let shopId=null; try{const j=JSON.parse(out.defaultShop); const s=JSON.stringify(j); const m=s.match(/"shopId":"(\d+)"|"id":"(\d+)","__typename":"RetailersShop/); shopId=m&&(m[1]||m[2]);}catch{}
out.shopId=shopId;
if(shopId){const r3=await fetch('/graphql?operationName=VisitShop',{method:'POST',credentials:'include',headers:{'content-type':'application/json'},body:JSON.stringify({operationName:'VisitShop',variables:{shopId,postalCode:ZIP,addressId:null},extensions:{persistedQuery:{version:1,sha256Hash:'d2845e5f0022f6d080bf14cd78dbcce9be2a277f12c468e7c43ff0d99a78e77a'}}})}); out.visit=(await r3.text()).slice(0,400);}
return JSON.stringify(out);
